-- Drawell DC-Series / DCW-Series refrigerated thermostatic baths and heating circulators: 28 models.
-- From the Drawell brochure. Photos: public/products/drawell/, logo: public/brands/drawell.png.
-- Run in Supabase -> SQL Editor (choose "Run without RLS" if asked). Safe to run again: products are updated by SKU.
alter table products add column if not exists features jsonb not null default '[]'::jsonb;
insert into brands (name, slug, website_url) values ('Drawell', 'drawell', 'https://www.drawellanalytical.com/')
on conflict (slug) do update set name = excluded.name, website_url = coalesce(brands.website_url, excluded.website_url);
insert into categories (name, slug, sort_order) values ('Equipment', 'equipment', 5) on conflict (slug) do nothing;

-- Old name-only Drawell placeholders (no photo, no details) are replaced by the full models below
delete from products where sku like 'DRW-EQU-%' and (image_url is null or image_url = '');

insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('DRAWELL-SDC-6', 'Drawell SDC-6 Refrigerated Thermostatic Bath (-5 to 100 °C, 6 L)', 'drawell-sdc-6-refrigerated-thermostatic-bath', 'The Drawell SDC-6 is a DC-Series refrigerated thermostatic bath and heating circulator with a 6 L stainless steel tank, working from -5 to 100 °C with ±0.05 °C stability. Use it for constant-temperature testing of samples and new products, or as a heat or cold source for direct and auxiliary heating or cooling. A built-in pump circulates the liquid to external equipment.', '[["Model", "SDC-6"], ["Series", "DC-Series"], ["Temperature range", "-5 to 100 °C"], ["Temperature stability", "±0.05 °C"], ["Display resolution", "0.1 °C"], ["Bath capacity", "6 L"], ["Tank size (L × W × D)", "260 × 200 × 140 mm"], ["Tank opening", "180 × 140 mm"], ["Pump head", "5 m"], ["Pump flow", "0 to 20 L/min"], ["Drain", "Yes"], ["Control", "Intelligent PID, TFT touch screen"], ["Refrigeration", "CFC-free, fully enclosed air-cooled compressor"]]', '["CFC-free refrigeration with a fully enclosed, air-cooled compressor for quiet running", "Compressor thermal overload protection", "Power-off protection with an automatic 3-minute restart delay", "TFT touch screen shows the working status at a glance", "Intelligent PID control adjusts heating and cooling automatically", "Settable upper and lower temperature alarms, plus over-heat alarm", "Inner tank in high-quality stainless steel", "Built-in circulation pump (5 m head, 0 to 20 L/min) to create a second constant-temperature field outside the bath", "Can supply cold liquid outside the tank to cool an external vessel", "Detects the temperature difference automatically for lower energy use", "Drain outlet for easy emptying"]', 'equipment', '/products/drawell/dc-series.jpg'),
